INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李克用以高思继兄弟为都将分掌幽州兵", "start_year": null, "end_year": null, "time_original": "李克用定幽州以后；本段背景，确年待考", "dynasty": "唐", "description": "妫州人高思继兄弟为燕人所服，李克用以其为都将，分掌幽州兵；其部下多山北豪强，刘仁恭忌惮他们。", "phases": [], "location_name": "幽州、妫州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a897f5a9-6624-5b17-8feb-77ba25ff3b6e"}, {"title": "高思继兄弟依法裁治暴横的河东戍兵", "start_year": null, "end_year": null, "time_original": "久之；幽州高氏掌兵以后，确年待考", "dynasty": "唐", "description": "河东戍幽州兵暴横，高思继兄弟依法裁治，诛杀多人。", "phases": [], "location_name": "幽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fbe5f875-c6ce-5004-a456-6053fe7089e0"}, {"title": "李克用责刘仁恭后杀高思继兄弟", "start_year": null, "end_year": null, "time_original": "高氏裁治戍兵以后；确年待考", "dynasty": "唐", "description": "李克用怒责刘仁恭，刘仁恭称系高氏兄弟所为，李克用杀高思继兄弟。", "phases": [], "location_name": "幽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e4b44e60-f604-55d4-bb60-7d839190da99"}, {"title": "刘仁恭收高氏诸子于帐下厚抚", "start_year": null, "end_year": null, "time_original": "高氏兄弟被杀以后；确年待考", "dynasty": "唐", "description": "刘仁恭为收燕人之心，将高氏兄弟诸子置于帐下，厚加抚恤。", "phases": [], "location_name": "幽州、帐下", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e6c9df7b-4f87-5032-93d4-8db68656176a"}, {"title": "崔昭纬向李茂贞王行瑜告朝廷机事", "start_year": null, "end_year": null, "time_original": "895年三月罢李磎以前；往来起点未载", "dynasty": "唐", "description": "崔昭纬与李茂贞、王行瑜深相结，将所知天子过失及朝廷机事告给二人。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "6e0ae63e-90c3-50d2-9b34-00dbcf77c79b"}, {"title": "崔昭纬使崔鋋向王行瑜诋毁韦昭度李磎", "start_year": 895, "end_year": 895, "time_original": "895年李磎再入相后；确日未载", "dynasty": "唐", "description": "李磎再次入相后，崔昭纬让同族、邠宁节度副使崔鋋向王行瑜指称韦昭度阻其尚书令任命，并与李磎相共惑主。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "8fa097e2-d638-557a-927d-ba629e3b7c8c"}, {"title": "王行瑜李茂贞表请罢李磎韦昭度", "start_year": 895, "end_year": 895, "time_original": "895年三月以前；确日未载", "dynasty": "唐", "description": "王行瑜与李茂贞上表称李磎奸邪、韦昭度无相业，请求罢为散秩。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "4470831b-cae3-57aa-9da2-676c25aef76c"}, {"title": "唐昭宗答命相当出朕怀", "start_year": 895, "end_year": 895, "time_original": "895年三月以前；确日未载", "dynasty": "唐", "description": "唐昭宗回复王行瑜等，称军旅可与藩镇议，任命宰相应出皇帝之意。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8057e2ec-2e66-5cd6-9673-637217d28cca"}, {"title": "李磎再罢相为太子少师", "start_year": 895, "end_year": 895, "time_original": "895年三月；具体日未载", "dynasty": "唐", "description": "王行瑜等不断论列，三月李磎再次罢相，为太子少师。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d9dc8f91-6137-52bf-b149-da6943c8279b"}, {"title": "王珙王瑶请朝廷命河中帅", "start_year": 895, "end_year": 895, "time_original": "895年三月条；确日未载", "dynasty": "唐", "description": "王珙、王瑶请求朝廷任命河中统帅。", "phases": [], "location_name": "河中、朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5a76dca7-b42a-568f-b423-a241e98277ef"}, {"title": "崔胤兼同平章事充护国节度使", "start_year": 895, "end_year": 895, "time_original": "895年三月条；确日未载", "dynasty": "唐", "description": "朝廷命中书侍郎、同平章事崔胤兼同平章事，充护国节度使。", "phases": [], "location_name": "护国、朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "039c920c-6b4b-589f-bc51-a9835f1b396b"}, {"title": "王抟授中书侍郎同平章事", "start_year": 895, "end_year": 895, "time_original": "895年三月条；确日未载", "dynasty": "唐", "description": "朝廷以户部侍郎、判户部王抟为中书侍郎、同平章事。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "73b9f484-3350-5b9d-b31f-486963f48f1d"}, {"title": "李克用表请赐王珂节钺", "start_year": 895, "end_year": 895, "time_original": "895年河中继立争议期间；确日未载", "dynasty": "唐", "description": "李克用上表称王重荣有功于国，请赐其子王珂节钺。", "phases": [], "location_name": "朝廷、河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "89c25d40-2294-59ee-bcda-835f12e47be4"}, {"title": "王珙结三帅，再表请交换珂珙辖镇", "start_year": 895, "end_year": 895, "time_original": "895年河中继立争议期间；确日未载", "dynasty": "唐", "description": "王珙厚结王行瑜、李茂贞、韩建，重申王珂非王氏子，要求王珂去陕州、自己领河中。", "phases": [], "location_name": "陕州、河中、朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2cf543d7-ba74-53da-b086-fc99bebf369f"}, {"title": "唐昭宗以已允李克用所奏拒王珙请求", "start_year": 895, "end_year": 895, "time_original": "895年王珙再表以后；确日未载", "dynasty": "唐", "description": "唐昭宗告谕王珙等，称先已允李克用所奏，不许交换王珂、王珙辖镇。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "224beb7a-84e0-5cde-8c0f-7d42ef685384"}, {"title": "王镕加兼侍中", "start_year": 895, "end_year": 895, "time_original": "895年三月条；确日未载", "dynasty": "唐", "description": "王镕加兼侍中。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "0d2187da-cf35-5e2a-b440-71505c4b9493"}, {"title": "杨行密至泗州，不悦台濛盛饰供帐", "start_year": 895, "end_year": 895, "time_original": "895年攻濠围寿之前；确日未载", "dynasty": "唐", "description": "杨行密沿淮至泗州，防御使台濛盛饰供帐，杨行密不悦。", "phases": [], "location_name": "淮河、泗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b44fe072-797c-5600-9d46-738e4ef08ede"}, {"title": "台濛使归补绽衣，杨行密言不忘本", "start_year": 895, "end_year": 895, "time_original": "895年离泗州以后；确日未载", "dynasty": "唐", "description": "杨行密离开后，台濛在卧内得补绽衣，使人追还。杨行密笑称幼年贫贱、不敢忘本，台濛惭。", "phases": [], "location_name": "泗州、卧内", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a109a3a2-2fb5-5ce6-82da-8d2532f205dc"}, {"title": "杨行密攻取濠州，执张璲", "start_year": 895, "end_year": 895, "time_original": "895年围寿以前；确日未载", "dynasty": "唐", "description": "杨行密攻下濠州，俘获刺史张璲。", "phases": [], "location_name": "濠州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "430d0812-9c37-5ebf-9782-5b47ed4d4569"}, {"title": "杨行密收养军士掠得的徐州李氏八岁子", "start_year": null, "end_year": null, "time_original": "攻濠条内追述幼年；确年待考", "dynasty": "唐", "description": "杨行密军士掠得徐州李氏八岁之子，杨行密将其收为养子，长子杨渥憎之。", "phases": [], "location_name": "徐州、濠州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "531419ef-cc2f-5df2-9217-eb090559b796"}, {"title": "杨行密将所养李氏子交徐温，徐温名知诰", "start_year": null, "end_year": null, "time_original": "收养后；确年待考", "dynasty": "唐", "description": "杨行密认为杨渥不能容新养子，将孩子赐给徐温为子；徐温为其取名知诰。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "bdc212af-98fe-5d77-83d5-7ec587086022"}, {"title": "徐知诰受笞逐后迎拜，徐温益爱之", "start_year": null, "end_year": null, "time_original": "徐温养知诰以后；尝，确年待考", "dynasty": "唐", "description": "知诰勤孝，曾因得罪徐温被笞逐，却仍在门迎拜，表示子不能离父母。徐温因此愈爱之。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "630f451a-8c84-59a5-a672-f03318d115df"}, {"title": "徐温使知诰掌家事", "start_year": null, "end_year": null, "time_original": "笞逐迎拜以后；确年待考", "dynasty": "唐", "description": "徐温让知诰管理家事，家人无违言。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "61176d03-f490-56d2-b98a-df62f96bb304"}, {"title": "知诰长成，杨行密称其俊杰", "start_year": null, "end_year": null, "time_original": "及长；幼年以后，确年待考", "dynasty": "唐", "description": "知诰长大后喜书善射，史书称其识度英伟。杨行密常向徐温称赞知诰俊杰、诸将子不及。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "39eea9f6-c87b-5338-8018-6eb620c9333d"}, {"title": "杨行密围寿州", "start_year": 895, "end_year": 895, "time_original": "895年三月丁亥", "dynasty": "唐", "description": "杨行密包围寿州。", "phases": [], "location_name": "寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ddbf56bd-5f12-5d38-bc3b-b587d361f786"}, {"title": "唐昭宗拟宗室巡警并抚慰藩镇", "start_year": 895, "end_year": 895, "time_original": "895年四月罢诏以前；确日未载", "dynasty": "唐", "description": "因郊畿盗贼甚至入宫、犯陵寝，唐昭宗拟让宗室诸王领兵巡警，并派往四方抚慰藩镇。", "phases": [], "location_name": "郊畿、宫、陵寝", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "af82cdce-2285-5d34-9648-2b988210942f"}, {"title": "南北司用事臣交章反对宗室领兵", "start_year": 895, "end_year": 895, "time_original": "895年四月以前；确日未载", "dynasty": "唐", "description": "南北司用事之臣担心宗室领兵不利于己，交章谏阻。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "559c4327-14df-586f-a853-546cf4868ca4"}, {"title": "唐昭宗诏罢宗室巡警抚慰计划", "start_year": 895, "end_year": 895, "time_original": "895年夏四月；具体日未载", "dynasty": "唐", "description": "唐昭宗不得已，下诏取消诸王领兵巡警及抚慰藩镇的计划。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "acd5c61c-c316-5251-9345-2b14afe7054e"}, {"title": "朝廷释董昌罪，纵归田里", "start_year": 895, "end_year": 895, "time_original": "895年四月条；具体日未载", "dynasty": "唐", "description": "朝廷以董昌曾勤于贡输，并认为其当下行为似患心疾，下诏释罪，允许其归田里。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ef689a20-a064-5a41-bbb0-020788a5618c"}]'::jsonb)
